sys_ws_operation.operation_script:
(function process(/*RESTAPIRequest*/ request, /*RESTAPIResponse*/ response) {

    var tasks = [];

    var gr = new GlideRecordSecure('x_2130921_caresy_0_clinical_task');
    gr.orderByDesc('due_date');
    gr.query();

    while (gr.next()) {

        tasks.push({
            sys_id: gr.getUniqueValue(),

            task_number: gr.getValue('number'),

            patient_sys_id: gr.getValue('patient'),
            patient: gr.getDisplayValue('patient'),

            admission_sys_id: gr.getValue('admission'),
            admission: gr.getDisplayValue('admission'),

            care_plan_sys_id: gr.getValue('care_plan'),
            care_plan: gr.getDisplayValue('care_plan'),

            task_name: gr.getValue('task_name'),
            task_type: gr.getDisplayValue('task_type'),

            assigned_to_sys_id: gr.getValue('assigned_to'),
            assigned_to: gr.getDisplayValue('assigned_to'),

            due_date: gr.getValue('due_date'),

            task_status: gr.getDisplayValue('task_status'),
            priority: gr.getDisplayValue('priority'),

            description: gr.getValue('description'),
            completion_date: gr.getValue('completion_date'),

            active: gr.getValue('active') == '1'
        });
    }

    response.setStatus(200);

    response.setBody({
        success: true,
        count: tasks.length,
        clinical_tasks: tasks
    });

})(request, response);
